from pathlib import Path
import json, re, glob, datetime, subprocess

ROOT = Path(__file__).resolve().parents[1]
if (ROOT/'requirements.md').exists() or (ROOT/'chat.txt').exists():
    raise SystemExit('初稿文件已存在；禁止重新生成并覆盖访谈、首次输出或后续人工修改。')
records=[]
for p in sorted(glob.glob(r'C:\Users\Administrator\.codex\sessions\2026\11\05\*01a1ab85*.jsonl')):
    for line in open(p, encoding='utf-8'):
        o=json.loads(line)
        if o['type']!='response_item': continue
        q=o['payload']
        if q.get('type')!='message' or q.get('role') not in ('user','assistant'): continue
        if q.get('role')=='assistant' and q.get('channel') not in (None,'final','commentary'): continue
        t=''.join(c.get('text','') for c in q.get('content',[]) if c.get('type') in ('input_text','output_text'))
        if not t.strip() or t.startswith(('<environment_context>','<external_codex_apps_open_page>')): continue
        records.append((o['timestamp'],q['role'],t))
records=sorted(set(records))
course=next(t for _,r,t in records if r=='user' and '# 实验一' in t)
cut=next(i for i,(_,r,t) in enumerate(records) if r=='user' and '行，那你完整的去做' in t)
records=records[:cut+1]
formal=[]; ai=[]; source_lines=[]; phase='INT-01'; counts={phase:0,'INT-02':0}
for ts,role,t in records:
    if '这轮正式访谈可以先结束' in t: phase='INT-02'
    when=datetime.datetime.fromisoformat(ts.replace('Z','+00:00')).astimezone(datetime.timezone(datetime.timedelta(hours=8))).isoformat(timespec='seconds')
    ai.append(f'### {when} / {"用户" if role=="user" else "AI"}\n\n{t}\n')
    if t==course: continue
    if '全部确认，正式访谈和跟进沟通可以结束' in t: continue
    for j,line in enumerate(t.splitlines()):
        counts[phase]+=1; ident=f'{phase}-L{counts[phase]:03d}'
        formal.append(f'{ident} [{when}] [{"用户" if role=="user" else "AI"}] {line}')
        source_lines.append((ident,line))

def src(words):
    found=[]
    for word in words.split('|'):
        matches=[i for i,l in source_lines if word in l]
        if matches: found.append(matches[-1])
    return '；'.join(dict.fromkeys(found)) or 'COURSE-02'

